  function resolveServer(button){
    const servers=state()?.servers||{};
    const fiberKey=Object.keys(button).find(k=>k.startsWith('__reactFiber$'));
    let fiber=fiberKey&&button[fiberKey];
    for(let i=0;fiber&&i<18;i++,fiber=fiber.return){
      const p=fiber.memoizedProps;
      for(const id of [p?.server?.id,p?.serverId,p?.sid,fiber.key])if(id&&servers[id])return id;
    }
    const src=button.querySelector('img')?.src;
    if(src&&api?.media){const found=Object.values(servers).filter(s=>api.media.publicUrl('icons',s.icon_path)===src);if(found.length===1)return found[0].id;}
    const title=button.getAttribute('aria-label')||button.title;const matches=Object.values(servers).filter(s=>s.name===title);return matches.length===1?matches[0].id:null;
  }
