    selfRoot?.remove();selfRoot=el('div',{'data-yappy-self':'','data-yappy-owned':'',class:'yappy-local-chat'});main.classList.add('yappy-main-host');main.append(selfRoot);document.querySelector('.app')?.classList.add('yappy-self-open');
