  const gifCache=new Map();
  async function findGifs(query,category){
    const categories=['hug','laugh','happy','wave','cry','angry','dance','smile','pat','shrug','sleep','thumbsup','wink','facepalm'];
    const q=query.trim().toLowerCase(),key=q+'|'+category;
    if(gifCache.has(key)&&Date.now()-gifCache.get(key).at<60000)return gifCache.get(key).items;
    let url;if(!q||categories.includes(q))url=`https://nekos.best/api/v2/${encodeURIComponent(q||category)}?amount=12`;
    else url='https://nekos.best/api/v2/search?'+new URLSearchParams({query:query.trim(),type:'2',amount:'12'});
    const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);
    try{const response=await nativeFetch(url,{credentials:'omit',signal:controller.signal});if(!response.ok)throw Error(response.status===429?'GIF search is busy. Try again shortly.':`GIF search returned ${response.status}.`);
      const data=await response.json();const items=(data.results||[]).filter(i=>safeImageUrl(i.url)).map(i=>({url:i.url,content:i.url,name:i.anime_name||q||category,type:'gif'}));gifCache.set(key,{at:Date.now(),items});return items;
    }finally{clearTimeout(timeout);}
  }
