      for(const key of ['font','panelOpacity','blur','modalBlur','wallpaperDim'])if(Number.isFinite(p.settings[key]))clean[key]=p.settings[key];clean.transparency=!!p.settings.transparency;clean.backgroundAsset='';clean.backgroundName='';
