      const icon=input(item.icon||'','Emoji, symbol or image URL');icon.setAttribute('aria-label','Icon '+(i+1));icon.addEventListener('change',()=>{item.icon=icon.value.trim().slice(0,2000);delete item.iconAsset;saveSettings();});
      const file=el('input',{type:'file',accept:'image/png,image/jpeg,image/webp,image/gif',hidden:true,'aria-label':'Action image '+(i+1)});
      file.addEventListener('change',async()=>{try{const f=file.files?.[0];if(!f)return;if(f.size>5*1024*1024)throw Error('Choose an image under 5 MB');const key='action-icon:'+crypto.randomUUID();if(!await keepBlob(key,f))throw Error('Could not save icon');item.iconAsset=key;saveSettings();}catch(e){toast(e.message);}});
      const stickers=el('select',{'aria-label':'Saved sticker '+(i+1)},el('option',{value:''},'Choose a saved emoji'),...stickerLibrary.slice(0,250).map(s=>el('option',{value:s.url},s.name)));
