    for(const row of body.querySelectorAll('.pick-row:not([data-yappy-search-member])')){const p=state()?.profiles?.[rowUserId(row)],text=(row.querySelector('.pick-row-name')||row).textContent+' '+(p?.username||'')+' '+(p?.display_name||'');row.toggleAttribute('data-yappy-filtered',!!q&&!normalSearch(text).includes(q));if(!row.hasAttribute('data-yappy-filtered'))matches++;}
